def explore(interests=None, query=None, route=None):
    """Careers that match interest codes, a free-text query and/or a route, best matches first."""
    interests = [code for code in (interests or []) if code in INTERESTS]
    words = [w for w in (query or '').casefold().replace(',', ' ').split() if len(w) > 2]
    scored = []
    for career in CAREERS:
        if route and route not in career['routes']:
            continue
        score = sum(3 - min(2, career['interests'].index(code)) for code in interests if code in career['interests'])
        haystack = ' '.join([career['name'], career['what_they_do'], career['study_path'], *career['school_subjects']]).casefold()
        score += sum(2 for w in words if w in haystack)
        if (interests or words) and not score:
            continue
        scored.append((score, career))
    scored.sort(key=lambda item: -item[0])
    return {
        'careers': [career for _, career in scored[:6]],
        'interest_meanings': {code: INTERESTS[code] for code in interests},
        'note': 'Typical study paths in Maharashtra; check each college and exam body for current rules. No salary or admission figures are given.',
    }
